"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type MorphPrimitiveProps = ComponentProps<typeof motion.div> & { layoutId?: string };

export function MorphPrimitive({ children, layoutId = "shared-motion-element", ...props }: MorphPrimitiveProps) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.div
      {...props}
      layout={"position"}
      layoutId={layoutId}
      initial={reduceMotion ? false : { opacity: 0, y: 48, scale: 0.86 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.26, ease: [0.23, 1, 0.32, 1] }}
      data-continuity="morph"
    >
      {children}
    </motion.div>
  );
}
